#!/usr/bin/env python3
"""news-image-20261120: 'The World in One Day' - Friday 20 November 2026.

A one-page newspaper front sheet summing up one day of world news.
Everything is drawn as flat vector geometry in code: filled polygons,
circles and thick strokes for the illustrations. Text is set in two
real typefaces - Playfair Display (Bold for the masthead, headlines
and figure numerals; Italic for the dek) and Open Sans (Regular, Bold
and ExtraBold for bodies, labels and bands) - whose glyph outline
contours and advance widths were extracted from the font files at
build time and are embedded below as data. The rasterizer is original
code: contours are flattened and scanline-filled under the nonzero
winding rule on a 4096x4096 canvas, then box-downscaled to 1024x1024
so edges are smooth. Python standard library only. Fully
deterministic.
"""

import math
import os
import struct
import zlib

# ------------------------------------------------------------------ canvas
SS = 4                      # supersampling factor
W = 1024                    # final width / height
W4 = W * SS                 # render width / height

PAPER = (245, 241, 229)     # warm cream paper
PANEL = (253, 250, 242)     # panel card
TINT = (241, 234, 217)      # pale art tint
INK = (27, 28, 30)          # near-black ink
GREY = (105, 98, 88)        # secondary ink
DARK = (85, 83, 75)         # warm dark grey for captions / micro-labels
RULE = (199, 189, 167)      # hairlines
RED = (179, 36, 30)         # the one accent
BLUE = (46, 78, 120)
TEAL = (38, 102, 96)
GREEN = (66, 110, 60)
GOLD = (176, 128, 32)
BROWN = (128, 88, 54)
NAVY = (22, 30, 54)
SKY = (198, 218, 232)
SEA = (92, 138, 170)
SAND = (219, 196, 150)
WHITE = (255, 255, 255)

FB = bytearray(bytes(PAPER) * (W4 * W4))


def _span(y, x0, x1, c):
    if y < 0 or y >= W4:
        return
    if x0 < 0:
        x0 = 0
    if x1 > W4 - 1:
        x1 = W4 - 1
    if x1 < x0:
        return
    off = y * W4 * 3 + x0 * 3
    FB[off:off + (x1 - x0 + 1) * 3] = bytes(c) * (x1 - x0 + 1)


def fill_rect(x, y, w, h, c):
    x0 = int(round(x * SS))
    y0 = int(round(y * SS))
    x1 = int(round((x + w) * SS)) - 1
    y1 = int(round((y + h) * SS)) - 1
    if x1 < x0 or y1 < y0:
        return
    row = bytes(c) * (x1 - x0 + 1)
    n = len(row)
    for yy in range(y0, y1 + 1):
        off = yy * W4 * 3 + x0 * 3
        FB[off:off + n] = row


def fill_circle(cx, cy, r, c):
    cx *= SS
    cy *= SS
    r *= SS
    y0 = int(cy - r)
    y1 = int(cy + r)
    r2 = r * r
    for yy in range(y0, y1 + 1):
        dy = yy - cy
        d2 = r2 - dy * dy
        if d2 < 0:
            continue
        dx = int(math.sqrt(d2))
        _span(yy, int(cx - dx), int(cx + dx), c)


def fill_ellipse(cx, cy, rx, ry, c):
    cx *= SS
    cy *= SS
    rx *= SS
    ry *= SS
    y0 = int(cy - ry)
    y1 = int(cy + ry)
    for yy in range(y0, y1 + 1):
        dy = (yy - cy) / ry
        d2 = 1.0 - dy * dy
        if d2 < 0:
            continue
        dx = int(rx * math.sqrt(d2))
        _span(yy, int(cx - dx), int(cx + dx), c)


def fill_poly(pts, c):
    """Scanline fill of a polygon given in final-image coordinates."""
    p = [(x * SS, y * SS) for (x, y) in pts]
    ys = [q[1] for q in p]
    y0 = max(0, int(min(ys)))
    y1 = min(W4 - 1, int(max(ys)))
    n = len(p)
    for yy in range(y0, y1 + 1):
        yc = yy + 0.5
        xs = []
        for i in range(n):
            xa, ya = p[i]
            xb, yb = p[(i + 1) % n]
            if (ya <= yc < yb) or (yb <= yc < ya):
                xs.append(xa + (yc - ya) * (xb - xa) / (yb - ya))
        if len(xs) < 2:
            continue
        xs.sort()
        for i in range(0, len(xs) - 1, 2):
            _span(yy, int(xs[i]), int(xs[i + 1]), c)


def thick_line(x0, y0, x1, y1, w, c):
    """A line drawn as stamped discs: round caps, even weight."""
    r = w * SS / 2.0
    dx = (x1 - x0) * SS
    dy = (y1 - y0) * SS
    dist = math.hypot(dx, dy)
    steps = max(1, int(dist / max(1.0, r * 0.55)))
    r2 = r * r
    ri = int(r)
    for i in range(steps + 1):
        t = i / steps
        cx = (x0 * SS) + dx * t
        cy = (y0 * SS) + dy * t
        for yy in range(int(cy) - ri, int(cy) + ri + 1):
            ddy = yy - cy
            d2 = r2 - ddy * ddy
            if d2 < 0:
                continue
            ddx = int(math.sqrt(d2))
            _span(yy, int(cx - ddx), int(cx + ddx), c)


def polyline(pts, w, c, close=False):
    pp = list(pts)
    if close and pp:
        pp.append(pp[0])
    for i in range(len(pp) - 1):
        thick_line(pp[i][0], pp[i][1], pp[i + 1][0], pp[i + 1][1], w, c)


def outline_rect(x, y, w, h, lw, c):
    fill_rect(x, y, w, lw, c)
    fill_rect(x, y + h - lw, w, lw, c)
    fill_rect(x, y, lw, h, c)
    fill_rect(x + w - lw, y, lw, h, c)


def arc_pts(cx, cy, rx, ry, a0, a1, n=14):
    """Points along an ellipse arc; angles in degrees, 0 = east,
    positive angles go DOWN the page (screen coordinates)."""
    out = []
    for i in range(n + 1):
        a = math.radians(a0 + (a1 - a0) * i / n)
        out.append((cx + rx * math.cos(a), cy + ry * math.sin(a)))
    return out

