# ------------------------------------------------------- real-font engine
# Text is set in real typefaces: glyph outline contours (TrueType
# quadratic segments) and advance widths extracted from the font files
# at build time and embedded in this file as FONT_DATA. The rasterizer is
# original code: contours are flattened to polylines, then filled with
# a nonzero-winding scanline fill on the 4x canvas. `size` everywhere
# is the em size in final-image pixels; (x, y) is the baseline start.

def _quad(out, p0, p1, p2, depth=0):
    """Append points of a quadratic Bezier segment to `out`,
    subdividing until the control point sits within ~2 font units of
    the chord (max deviation ~1 unit, sub-pixel at every used size)."""
    mx = (p0[0] + p2[0]) / 2.0
    my = (p0[1] + p2[1]) / 2.0
    if abs(p1[0] - mx) + abs(p1[1] - my) <= 2.0 or depth >= 10:
        out.append(p2)
        return
    a = ((p0[0] + p1[0]) / 2.0, (p0[1] + p1[1]) / 2.0)
    b = ((p1[0] + p2[0]) / 2.0, (p1[1] + p2[1]) / 2.0)
    c = ((a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0)
    _quad(out, p0, a, c, depth + 1)
    _quad(out, c, b, p2, depth + 1)


def _flatten_contour(pts):
    """One TrueType contour ((x, y, on_curve) ...) -> closed polyline
    of (x, y) font-unit points. Off-curve runs use implied on-curve
    points midway between neighbouring control points."""
    n = len(pts)
    if n < 2:
        return [(p[0], p[1]) for p in pts]
    if pts[0][2]:
        start = (pts[0][0], pts[0][1])
        rest = list(pts[1:]) + [pts[0]]
    elif pts[-1][2]:
        start = (pts[-1][0], pts[-1][1])
        rest = list(pts[:-1]) + [pts[-1]]
    else:
        start = ((pts[0][0] + pts[-1][0]) / 2.0,
                 (pts[0][1] + pts[-1][1]) / 2.0)
        rest = list(pts) + [(start[0], start[1], 1)]
    out = [start]
    cur = start
    i = 0
    while i < len(rest):
        p = rest[i]
        if p[2]:
            cur = (p[0], p[1])
            out.append(cur)
            i += 1
        else:
            q = rest[i + 1]
            _quad(out, cur, (p[0], p[1]), (q[0], q[1]))
            cur = (q[0], q[1])
            i += 2
    return out


_FLAT = {}


def _glyph(font, ch):
    """(advance_units, [flattened contour polylines]) for one glyph,
    flattened once and cached."""
    key = (font, ch)
    got = _FLAT.get(key)
    if got is None:
        upem, _cap, _xh, glyphs = FONT_DATA[font]
        adv, contours = glyphs.get(ch) or glyphs[' ']
        got = (adv, [_flatten_contour(c) for c in contours])
        _FLAT[key] = got
    return got


def _fill_nz(polys, c):
    """Nonzero-winding scanline fill of closed polylines given in
    final-image coordinates - the TrueType fill rule, so counters and
    bowls land exactly as the font designer drew them."""
    edges = []
    ys = []
    for poly in polys:
        if len(poly) < 2:
            continue
        p = [(x * SS, y * SS) for (x, y) in poly]
        ys += [q[1] for q in p]
        m = len(p)
        for i in range(m):
            xa, ya = p[i]
            xb, yb = p[(i + 1) % m]
            if ya != yb:
                edges.append((xa, ya, xb, yb))
    if not edges:
        return
    y0 = max(0, int(min(ys)))
    y1 = min(W4 - 1, int(max(ys)))
    for yy in range(y0, y1 + 1):
        yc = yy + 0.5
        hits = []
        for xa, ya, xb, yb in edges:
            if (ya <= yc < yb) or (yb <= yc < ya):
                hits.append((xa + (yc - ya) * (xb - xa) / (yb - ya),
                             1 if yb > ya else -1))
        if len(hits) < 2:
            continue
        hits.sort()
        wind = 0
        for i in range(len(hits) - 1):
            wind += hits[i][1]
            if wind:
                _span(yy, int(hits[i][0]), int(hits[i + 1][0]), c)


def text_width(s, size, font, tracking=0.0):
    """Measured advance width of a line, from the real font metrics."""
    upem = FONT_DATA[font][0]
    scale = size / upem
    w = 0.0
    for ch in s:
        w += _glyph(font, ch)[0] * scale
    if len(s) > 1:
        w += tracking * (len(s) - 1)
    return w


def draw_text(x, y, s, size, color, font, tracking=0.0, align='l'):
    """One line of real-font text; (x, y) is the baseline start and
    `size` is the em size in final-image pixels."""
    upem = FONT_DATA[font][0]
    scale = size / upem
    w = text_width(s, size, font, tracking)
    if align == 'c':
        x -= w / 2.0
    elif align == 'r':
        x -= w
    cx = x
    for ch in s:
        adv, contours = _glyph(font, ch)
        if contours:
            polys = [[(cx + px * scale, y - py * scale) for (px, py) in con]
                     for con in contours]
            _fill_nz(polys, color)
        cx += adv * scale + tracking
    return cx


def wrap_text(s, size, font, maxw, tracking=0.0):
    """Greedy word wrap on measured advance widths."""
    words = s.split(' ')
    lines = []
    cur = ''
    for wd in words:
        trial = wd if not cur else cur + ' ' + wd
        if text_width(trial, size, font, tracking) <= maxw or not cur:
            cur = trial
        else:
            lines.append(cur)
            cur = wd
    if cur:
        lines.append(cur)
    return lines


def draw_wrapped(x, y, s, size, color, font, maxw, lh, tracking=0.0,
                 max_lines=None):
    """Wrapped block starting with baseline y; returns last baseline."""
    lines = wrap_text(s, size, font, maxw, tracking)
    if max_lines is not None:
        lines = lines[:max_lines]
    yy = y
    for ln in lines:
        draw_text(x, yy, ln, size, color, font, tracking)
        yy += lh
    return yy - lh


def fit_size(s, size, font, maxw, tracking=0.0, floor=1.0):
    """Largest em size, at or below `size` in quarter steps, at which
    this single line fits `maxw` on measured metrics."""
    while size > floor and text_width(s, size, font, tracking) > maxw:
        size -= 0.25
    return size


def draw_region(x, y, s, maxw, size=12.5, floor=10.0, color=DARK,
                tracking=0.1):
    """Region/source line in bold sans, auto-fitted down from its
    nominal size only as far as the available width forces."""
    size = fit_size(s, size, 'SANS_B', maxw, tracking, floor)
    draw_text(x, y, s, size, color, 'SANS_B', tracking=tracking)

# ------------------------------------------------------------------ output
# Solid-stroke curve applied to the box-downscaled image: a gentle power
# remap that pulls mid-grey anti-aliasing fringe toward the ink value, so
# letters land as solid strokes with no semi-transparent grey halo, while
# flat art fills (uniform values) stay uniform. Endpoints are exact.
_SOLID = bytes(max(0, min(255, round(255.0 * (v / 255.0) ** 1.28)))
               for v in range(256))


def downscale():
    """Box-downscale the 4096 canvas to 1024 with SWAR big-int sums:
    each byte is spread into a 16-bit lane, rows and neighbours are added
    in parallel, then shifted back - exact 4x4 means, C speed."""
    out = bytearray(W * W * 3)
    stride4 = W4 * 3
    for oy in range(W):
        ints = []
        for dy in range(SS):
            row = bytes(FB[(oy * SS + dy) * stride4:
                           (oy * SS + dy) * stride4 + stride4])
            ba = bytearray(len(row) * 2)
            ba[0::2] = row
            ints.append(int.from_bytes(ba, 'little'))
        v = ints[0] + ints[1] + ints[2] + ints[3]
        h = v + (v >> 48) + (v >> 96) + (v >> 144)
        res = (h >> 4).to_bytes(len(row) * 2, 'little')
        # Lane 3p+c of the sum holds buffer pixels p..p+3, so output
        # pixel p (buffer pixels 4p..4p+3) sits at lane 12p+c: gather
        # each channel with a 24-byte stride, then interleave.
        orow = bytearray(W * 3)
        orow[0::3] = res[0::24]
        orow[1::3] = res[2::24]
        orow[2::3] = res[4::24]
        out[oy * W * 3:(oy + 1) * W * 3] = orow.translate(_SOLID)
    return bytes(out)


def save_png(path):
    raw = downscale()
    stride = W * 3
    scan = bytearray()
    for yy in range(W):
        scan.append(0)
        scan += raw[yy * stride:(yy + 1) * stride]
    comp = zlib.compress(bytes(scan), 6)

    def chunk(tag, data):
        return (struct.pack('>I', len(data)) + tag + data +
                struct.pack('>I', zlib.crc32(tag + data) & 0xffffffff))

    png = b'\x89PNG\r\n\x1a\n'
    png += chunk(b'IHDR', struct.pack('>IIBBBBB', W, W, 8, 2, 0, 0, 0))
    png += chunk(b'IDAT', comp)
    png += chunk(b'IEND', b'')
    with open(path, 'wb') as f:
        f.write(png)


